input.command:
$ev = Get-Content docs/a5/sessions/session-6.jsonl -Encoding UTF8 | Where-Object { $_.Trim() } | ForEach-Object { $_ | ConvertFrom-Json }
"count: $($ev.Count)"; ($ev | Group-Object type | ForEach-Object { "$($_.Name)=$($_.Count)" }) -join ', '
"last type: $($ev[-1].type)"
$r = $ev | Where-Object { $_.type -eq 'result' } | Select-Object -Last 1
"num_turns=$($r.num_turns) duration_ms=$($r.duration_ms) subtype=$($r.subtype) is_error=$($r.is_error)"
$r.result | Out-File -Encoding utf8 "$env:TEMP\s6_result.txt"
$tu = $ev | Where-Object { $_.type -eq 'assistant' } | ForEach-Object { $_.message.content } | Where-Object { $_.type -eq 'tool_use' }
$tu | Group-Object name | ForEach-Object { "$($_.Name)=$($_.Count)" }
$cmds = $tu | Where-Object { $_.name -eq 'Bash' } | ForEach-Object { [string]$_.input.command }
($cmds -join "`n<<<SEP>>>`n") | Out-File -Encoding utf8 "$env:TEMP\s6_bash.txt"
"bash count: $(@($cmds).Count)"
$env:TEMP

